mkdir -p "$TEMP/firstlight-shot" && cat > "$TEMP/firstlight-shot/shot.js" <<'JSEOF'
const { chromium } = require('C:/Users/t430/3D Objects/coding/projects/dip/node_modules/playwright');

const OUT = 'C:/Users/t430/3D Objects/coding/projects/portfolio/public/images/firstlight.jpg';

(async () => {
  const browser = await chromium.launch({
    executablePath: 'C:/Program Files/Google/Chrome/Application/chrome.exe',
    headless: true,
  });
  const page = await browser.newPage({ viewport: { width: 1600, height: 900 } });

  await page.goto('http://127.0.0.1:8000/index.php', { waitUntil: 'load' });
  await page.fill('input[name="name"]', 'Alex');

  // The birthday uses a hidden native date input behind the calendar; set it directly.
  await page.evaluate(() => {
    const input = document.getElementById('birthday-native');
    input.value = '1990-10-24';
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
  });

  // Birth place: search, then choose the Lusaka, Zambia suggestion.
  await page.fill('#place-search', 'Lusaka');
  await page.waitForSelector('#place-results [role="option"]', { timeout: 30000 });
  const labels = await page.$$eval('#place-results [role="option"]', (els) => els.map((e) => e.textContent));
  const index = labels.findIndex((t) => /Zambia/.test(t));
  if (index < 0) throw new Error('No Zambia option. Options: ' + labels.join(' | '));
  await page.locator('#place-results [role="option"]').nth(index).dispatchEvent('mousedown');

  await Promise.all([
    page.waitForURL('**/result.php', { timeout: 180000 }),
    page.click('button[type="submit"]'),
  ]);

  // Wait for the city photo to finish loading before the screenshot.
  await page.waitForFunction(() => {
    const img = document.querySelector('img.hero');
    return img && img.complete && img.naturalWidth > 0;
  }, null, { timeout: 120000 }).catch(() => console.log('city photo did not load in time'));
  await page.
